import Card from "@/core/components/primitives/card/card";
import styles from "./backstage-infoscreen-multiple-block.module.less";
import { useEffect, useState } from "react";
import { motion } from "framer-motion";
import { DateHelper, multipleClassNames } from "@/core/helpers";
import { useVerticalScroll } from "@/core/hooks";
import { IBackstageInfoscreenService } from "@/core/services";
import { ExistingThemes, MediaModule, Message } from "@/core/types";
import Banner from "@/core/components/primitives/banner/banner";

type Props = {
  heading: string;
  count: number;
  backstageInfoService: IBackstageInfoscreenService;
  autoScroll?: boolean;
  scrollSpeed?: number;
  componentTheme?: ExistingThemes;
};

const REFRESH_INTERVAL = 1_000 * 60 * 1;

const BackstageInfoscreenMultipleBlock = ({
  heading,
  count,
  backstageInfoService,
  autoScroll = false,
  scrollSpeed = 20,
  componentTheme,
}: Props) => {
  const [messages, setMessages] = useState<Array<Message>>([]);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [controls, refCallback] = useVerticalScroll(scrollSpeed);

  useEffect(() => {
    async function fetchData() {
      try {
        const data = await backstageInfoService.getBackstageMultipleMessages(count);
        setMessages(data);
      } catch (error) {
        setErrorMessage("Kunde inte hämta information just nu. Försök igen senare.");
      }
    }
    fetchData();
    const intervalId = setInterval(fetchData, REFRESH_INTERVAL);

    return () => clearInterval(intervalId);
  }, [backstageInfoService, count]);

  return (
    <section className={multipleClassNames(styles.outerWrapper, componentTheme)}>
      <motion.div animate={autoScroll ? controls : undefined}>
        <h1>{heading}</h1>
        <div>
          {messages.map((message, index) => {
            const isLast = index === messages.length - 1;
            const largestImageIfExist = getLargestImageIfExist(message);
            const hasImage = !!largestImageIfExist;
            return (
              <Card
                ref={isLast ? refCallback : undefined}
                key={index}
                className={styles.card}
                data-has-image={hasImage}
              >
                <div className={styles.textWrapper}>
                  <h2 key={index}>{message.channelPushTitle ?? message.subject}</h2>
                  <p>{message.channelPushBody ?? message.oneLiner}</p>
                  <p className={styles.published}>
                    {DateHelper.toStringMMDDWeekday(message.firstPublished)}{" "}
                    {DateHelper.toStringTimeHHMM(message.firstPublished)}
                  </p>
                </div>

                {largestImageIfExist && (
                  <div className={styles.cardImage}>
                    <img className={styles.image} src={largestImageIfExist.url} alt={message.subject} />
                  </div>
                )}
              </Card>
            );
          })}
        </div>
        {errorMessage && <Banner type="critical" heading="Något gick fel" paragraph={errorMessage} />}
      </motion.div>
    </section>
  );
};

const getLargestImageIfExist = (message: Message) => {
  const mediaModule = message.modules.find((module) => module.type === "media") as MediaModule | undefined;
  if (!mediaModule) {
    return undefined;
  }
  const image = [...mediaModule.media[0].images].sort((a, b) => b.size.width - a.size.width)[0];
  return image;
};

export default BackstageInfoscreenMultipleBlock;
